/**
 * @az module generated
 * Purpose: the one-line header every generated file opens with — what the file is, and where the map is.
 * Spec: docs/ARCHITECTURE.md §7
 * Exports: generated, generatedJson, generatedMd, AZ_MAP
 * Edit guide: keep the "GENERATED BY AZ" prefix — tests and tools match on it; keep it one line.
 * Tests: packages/target-web/test/emit.test.ts, packages/target-web/test/azmd.test.ts
 */

/** The generated project's map for people and AI tools (azmd.ts). */
export const AZ_MAP = 'AZ.md';

const tail = `Do not edit: change the .az source and rebuild (map: ${AZ_MAP})`;

/** A code or CSS file's first line: what it is, and that the .az file is the source. */
export const generated = (what: string): string => `/* GENERATED BY AZ — ${what}. ${tail}. */\n`;

/** JSON takes no comment, so the same statement rides as `_generated` data. */
export const generatedJson = (what: string): string => `BY AZ — ${what}. ${tail}.`;

/** Markdown's first line, as an HTML comment so it does not render. */
export const generatedMd = (what: string): string => `<!-- GENERATED BY AZ — ${what}. ${tail}. -->\n`;
